// ---- js/state.js ----
(function(){
'use strict';
// state.js — project/element store with undo-redo and persistence.
const { Emitter, uid, deepClone } = WF;
const { makeElement } = WF;
const LS_KEY = "webfacer.project.v1";

function newAnimClip() {
  return {
    id: uid("anim"),
    label: "动画",
    start: 0,          // ms — when it starts on the master timeline
    duration: 600,     // ms
    tracks: [
      { prop: "opacity", keyframes: [
        { t: 0, value: "0", ease: "ease" },
        { t: 1, value: "1", ease: "ease" },
      ] },
    ],
  };
}

class Store extends Emitter {
  constructor() {
    super();
    this.project = this._emptyProject();
    this.history = [];
    this.future = [];
    this._historyLock = 0;
    this.hidden = new Set(); // transient visibility (not persisted)
    this.clip = null;        // internal clipboard for copy/paste
  }

  _emptyProject() {
    return {
      id: uid("proj"),
      name: "未命名项目",
      width: 1200,
      height: 800,
      zoom: 1,
      selectedId: null,
      selectedIds: [],
      canvasBg: "#ffffff",
      showGrid: false,
      logic: [],
      elements: [],
    };
  }

  get state() { return this.project; }

  // ----- event-safe mutation -----
  _emit(reason) { this.emit("change", reason); }

  // ------ history ------
  pushHistory() {
    if (this._historyLock > 0) return;
    this.history.push(this._snapshot());
    if (this.history.length > 200) this.history.shift();
    this.future = [];
  }
  _snapshot() {
    const p = this.project;
    return {
      name: p.name, width: p.width, height: p.height,
      canvasBg: p.canvasBg, showGrid: p.showGrid,
      logic: deepClone(p.logic || []),
      elements: deepClone(p.elements),
    };
  }
  _restore(snap) {
    const p = this.project;
    p.name = snap.name;
    p.width = snap.width;
    p.height = snap.height;
    p.canvasBg = snap.canvasBg;
    p.showGrid = snap.showGrid;
    p.logic = snap.logic || [];
    p.elements = snap.elements;
    // drop selection if removed
    if (p.selectedId && !this._findAny(p.selectedId)) { p.selectedId = null; p.selectedIds = []; }
    p.selectedIds = (p.selectedIds || []).filter(id => this._findAny(id));
  }
  get canUndo() { return this.history.length > 0; }
  get canRedo() { return this.future.length > 0; }
  undo() {
    if (!this.canUndo) return;
    this.future.push(this._snapshot());
    this._restore(this.history.pop());
    this._emit({ type: "structure" });
    this._emit({ type: "selection" });
  }
  redo() {
    if (!this.canRedo) return;
    this.history.push(this._snapshot());
    this._restore(this.future.pop());
    this._emit({ type: "structure" });
    this._emit({ type: "selection" });
  }

  // ------ element queries ------
  isHidden(id) { return this.hidden.has(id); }
  toggleHidden(id) {
    if (this.hidden.has(id)) this.hidden.delete(id); else this.hidden.add(id);
    this._emit({ type: "update", id });
  }
  elements() { return this.project.elements; }
  getElement(id) { return this.project.elements.find(e => e.id === id) || null; }
  _findAny(id) {
    return this.project.elements.find(e => e.id === id) || null;
  }
  childrenOf(id) { return this.project.elements.filter(e => e.parentId === id); }
  _descendants(id) {
    const out = [];
    const walk = (pid) => {
      this.project.elements.forEach(e => {
        if (e.parentId === pid) { out.push(e.id); walk(e.id); }
      });
    };
    walk(id);
    return out;
  }

  // ------ selection ------
  select(id) {
    if (!this._findAny(id)) return;
    this.project.selectedId = id;
    this.project.selectedIds = [id];
    this._emit({ type: "selection", id });
  }
  addToSelection(id) {
    if (!this._findAny(id)) return;
    const ids = this.project.selectedIds;
    if (!ids.includes(id)) ids.push(id);
    this.project.selectedId = id;
    this._emit({ type: "selection" });
  }
  toggleSelect(id) {
    if (!this._findAny(id)) return;
    const ids = this.project.selectedIds;
    if (ids.includes(id)) ids.splice(ids.indexOf(id), 1);
    else ids.push(id);
    this.project.selectedId = ids.length ? ids[ids.length - 1] : null;
    this._emit({ type: "selection" });
  }
  setSelection(ids) {
    this.project.selectedIds = ids.filter(id => this._findAny(id));
    this.project.selectedId = this.project.selectedIds.length ? this.project.selectedIds[this.project.selectedIds.length - 1] : null;
    this._emit({ type: "selection" });
  }
  clearSelection() {
    if (this.project.selectedId == null && this.project.selectedIds.length === 0) return;
    this.project.selectedId = null;
    this.project.selectedIds = [];
    this._emit({ type: "selection", id: null });
  }
  isSelected(id) { return this.project.selectedIds.includes(id); }
  selected() { return this.project.selectedIds.slice(); }
  get multiSelected() { return this.project.selectedIds.length > 1; }

  // ------ mutations ------
  addElement(typeKey, opts = {}) {
    this.pushHistory();
    const el = makeElement(typeKey, opts);
    el.id = uid(el.type);
    if (opts.name) el.name = opts.name;
    // default position: keep within canvas, offset to avoid stacking
    const placed = this._placement(el, opts);
    el.x = placed.x; el.y = placed.y;
    if (opts.parentId) el.parentId = opts.parentId;
    this.project.elements.push(el);
    this._emit({ type: "add", id: el.id });
    return el;
  }

  _placement(el, opts) {
    let x = opts.x, y = opts.y;
    if (x == null || y == null) {
      const base = this.project.elements.filter(e => !e.parentId).length % 8;
      x = 60 + (base * 24);
      y = 60 + (base * 24);
    }
    return { x, y };
  }

  updateElement(id, patch, opts = {}) {
    const el = this.getElement(id);
    if (!el) return;
    if (opts.history !== false && this._historyLock === 0) this.pushHistory();
    const { props, ...rest } = patch;
    Object.assign(el, rest);
    if (props) Object.assign(el.props, props);
    this._emit({ type: "update", id });
  }

  removeElement(id) {
    const el = this.getElement(id);
    if (!el) return;
    this.pushHistory();
    const ids = new Set([id, ...this._descendants(id)]);
    this.project.elements = this.project.elements.filter(e => !ids.has(e.id));
    this.project.logic = (this.project.logic || []).filter(l => !ids.has(l.triggerId) && !ids.has(l.targetId));
    this.project.selectedIds = this.project.selectedIds.filter(sid => !ids.has(sid));
    if (this.project.selectedId && ids.has(this.project.selectedId)) this.project.selectedId = null;
    this._emit({ type: "remove", id });
    this._emit({ type: "selection" });
    this._emit({ type: "logic" });
  }

  updateMany(ids, patch, opts = {}) {
    const list = [...new Set(ids)].map(id => this.getElement(id)).filter(Boolean);
    if (!list.length) return;
    if (opts.history !== false && this._historyLock === 0) this.pushHistory();
    for (const el of list) {
      if (patch.x != null) el.x = patch.x;
      if (patch.y != null) el.y = patch.y;
      if (patch.width != null) el.width = patch.width;
      if (patch.height != null) el.height = patch.height;
      if (patch.name != null) el.name = patch.name;
      if (patch.content != null) el.content = patch.content;
      if (patch.locked != null) el.locked = !!patch.locked;
      if (patch.props) Object.assign(el.props, patch.props);
    }
    this._emit({ type: "update-many" });
  }

  duplicateElement(id) {
    const src = this.getElement(id);
    if (!src) return;
    this.pushHistory();
    const clone = deepClone(src);
    clone.id = uid(src.type);
    clone.name = src.name + " 副本";
    clone.x = src.x + 24;
    clone.y = src.y + 24;
    this.project.elements.push(clone);
    // clone descendants too (simple: same parent)
    this.project.elements.forEach(e => {
      if (src.parentId && e.id !== clone.id && e.parentId === src.parentId) { /* no-op */ }
    });
    this._emit({ type: "add", id: clone.id });
    return clone;
  }

  // scale all elements (canvas resize)
  resizeCanvas(width, height) {
    this.pushHistory();
    this.project.width = width;
    this.project.height = height;
    this._emit({ type: "resize-canvas" });
  }

  setZoom(z) {
    this.project.zoom = Math.max(0.1, Math.min(4, Number(z) || 1));
    this._emit({ type: "zoom" });
  }
  setProjectName(name) {
    this.project.name = name;
    this._emit({ type: "meta" });
  }

  setCanvasBg(color) {
    this.pushHistory();
    this.project.canvasBg = color || "#ffffff";
    this._emit({ type: "canvas" });
  }
  toggleGrid() {
    this.pushHistory();
    this.project.showGrid = !this.project.showGrid;
    this._emit({ type: "canvas" });
  }

  // ----- alignment (single element relative to canvas) -----
  alignElement(id, which) {
    const el = this.getElement(id);
    if (!el) return;
    this.pushHistory();
    const W = this.project.width, H = this.project.height;
    const w = el.width, h = el.height;
    switch (which) {
      case "left": el.x = 0; break;
      case "center-x": el.x = (W - w) / 2; break;
      case "right": el.x = W - w; break;
      case "top": el.y = 0; break;
      case "center-y": el.y = (H - h) / 2; break;
      case "bottom": el.y = H - h; break;
      default: break;
    }
    this._emit({ type: "update", id });
  }

  // ----- z-order (later in array = rendered on top) -----
  moveZ(id, dir) {
    const arr = this.project.elements;
    const i = arr.findIndex(e => e.id === id);
    if (i < 0) return;
    this.pushHistory();
    const [el] = arr.splice(i, 1);
    let j = i;
    if (dir === "front") j = arr.length;
    else if (dir === "back") j = 0;
    else if (dir === "up") j = Math.min(arr.length, i + 1);
    else if (dir === "down") j = Math.max(0, i - 1);
    arr.splice(j, 0, el);
    this._emit({ type: "structure" });
  }

  setLocked(id, locked) {
    const el = this.getElement(id);
    if (!el) return;
    this.updateElement(id, { locked: !!locked });
  }

  // ----- animation clips (each element can have MULTIPLE clips at different times) -----
  animsOf(id) {
    const el = this.getElement(id);
    return (el && Array.isArray(el.anims)) ? el.anims : [];
  }
  getAnim(id, clipId) {
    return this.animsOf(id).find(a => a.id === clipId) || null;
  }
  addAnim(id, clip) {
    const el = this.getElement(id);
    if (!el) return null;
    this.pushHistory();
    if (!Array.isArray(el.anims)) el.anims = [];
    const c = Object.assign(newAnimClip(), clip, {
      id: (clip && clip.id) || uid("anim"),
      start: (clip && clip.start) != null ? clip.start : 0,
      duration: (clip && clip.duration) || 600,
      label: (clip && clip.label) || "动画",
    });
    el.anims.push(c);
    this._emit({ type: "update", id });
    return c;
  }
  updateAnim(id, clipId, patch = {}) {
    const a = this.getAnim(id, clipId);
    if (!a) return;
    this.pushHistory();
    if (patch.start != null) a.start = patch.start;
    if (patch.duration != null) a.duration = patch.duration;
    if (patch.label != null) a.label = patch.label;
    if (patch.tracks) a.tracks = patch.tracks;
    this._emit({ type: "update", id });
  }
  removeAnim(id, clipId) {
    const el = this.getElement(id);
    if (!el || !Array.isArray(el.anims)) return;
    this.pushHistory();
    el.anims = el.anims.filter(a => a.id !== clipId);
    this._emit({ type: "update", id });
  }
  clearProjectAnimations() {
    for (const e of this.project.elements) e.anims = [];
    this._emit({ type: "structure" });
  }

  // ----- click logic (trigger element -> animate target) -----
  logicEdges() { return this.project.logic || []; }
  logicFor(targetId) { return (this.project.logic || []).filter(l => l.targetId === targetId); }
  hasLogic(triggerId, targetId) {
    return (this.project.logic || []).some(l => l.triggerId === triggerId && l.targetId === targetId);
  }
  addLogicEdge(triggerId, targetId) {
    if (!this._findAny(triggerId) || !this._findAny(targetId)) return null;
    if (this.hasLogic(triggerId, targetId)) return null;
    this.pushHistory();
    if (!this.project.logic) this.project.logic = [];
    const edge = { id: uid("lg"), triggerId, targetId };
    this.project.logic.push(edge);
    this._emit({ type: "logic" });
    return edge;
  }
  removeLogicEdge(edgeId) {
    if (!(this.project.logic || []).some(l => l.id === edgeId)) return;
    this.pushHistory();
    this.project.logic = (this.project.logic || []).filter(l => l.id !== edgeId);
    this._emit({ type: "logic" });
  }

  // ----- copy / paste (internal clipboard) -----
  copyElement(id) {
    const el = this.getElement(id);
    if (!el) return null;
    this.clip = deepClone(el);
    this._emit({ type: "clipboard" });
    return this.clip;
  }
  get canPaste() { return !!this.clip; }
  pasteElement() {
    if (!this.clip) return null;
    this.pushHistory();
    const clone = deepClone(this.clip);
    clone.id = uid(clone.type);
    clone.name = (this.clip.name || this.clip.type) + " 副本";
    clone.x = (this.clip.x || 60) + 24;
    clone.y = (this.clip.y || 60) + 24;
    clone.parentId = null;
    this.project.elements.push(clone);
    this._emit({ type: "add", id: clone.id });
    return clone;
  }

  // ------ persistence ------
  toJSON() {
    const p = this.project;
    return {
      version: 1,
      project: {
        id: p.id, name: p.name, width: p.width, height: p.height, zoom: p.zoom,
        canvasBg: p.canvasBg, showGrid: p.showGrid,
        logic: p.logic || [],
        elements: p.elements,
      },
    };
  }
  saveLocal() {
    try { localStorage.setItem(LS_KEY, JSON.stringify(this.toJSON())); return true; }
    catch (e) { console.warn("save failed", e); return false; }
  }
  loadLocal() {
    try {
      const raw = localStorage.getItem(LS_KEY);
      if (!raw) return null;
      const data = JSON.parse(raw);
      if (!data.project) return null;
      this.loadProject(data.project);
      return this.project;
    } catch (e) { console.warn("load failed", e); return null; }
  }
  loadProject(p) {
    this.project = {
      id: p.id || uid("proj"),
      name: p.name || "未命名项目",
      width: p.width || 1200,
      height: p.height || 800,
      zoom: p.zoom || 1,
      selectedId: null,
      selectedIds: [],
      canvasBg: p.canvasBg || "#ffffff",
      showGrid: p.showGrid === true,
      logic: Array.isArray(p.logic) ? p.logic : [],
      elements: Array.isArray(p.elements) ? p.elements : [],
    };
    this.history = [];
    this.future = [];
    this._emit({ type: "structure" });
    this._emit({ type: "selection" });
    this._emit({ type: "zoom" });
  }
  newProject(opts = {}) {
    const p = this.project;
    const old = deepClone({ id: p.id, name: p.name, width: p.width, height: p.height, elements: p.elements });
    this.history.push(old);
    this.future = [];
    this.project = this._emptyProject();
    this.project.name = opts.name || "未命名项目";
    this.project.width = opts.width || 1200;
    this.project.height = opts.height || 800;
    this.project.id = uid("proj");
    this._emit({ type: "structure" });
    this._emit({ type: "selection" });
    this._emit({ type: "meta" });
    this._emit({ type: "zoom" });
  }
}

const store = new Store();

WF.store = store;
WF.Store = Store;
})();

// ---- js/render-css.js ----
(function(){
'use strict';
// render-css.js — convert elements to CSS text and HTML text (shared by preview & export).
const { slugify, escapeHtml } = WF;
// CSS props allowed to be emitted into a rule (everything else like geometry is handled separately)
const WHITELIST = new Set([
  "display", "width", "height", "flex-direction", "flex-wrap", "align-items",
  "justify-content", "gap", "font-family", "font-size", "font-weight", "line-height",
  "letter-spacing", "text-align", "text-decoration", "color", "background-color",
  "background-image", "background-size", "background-position", "border-width",
  "border-style", "border-color", "border-radius", "box-shadow", "opacity",
  "transform", "transition", "object-fit", "overflow", "cursor", "margin", "padding",
]);

// values that are effectively "empty" and should be omitted to keep output clean
const EMPTY = new Set(["0", "0px", "0px 0px", "none", "transparent", "inherit", ""]);

function num(v) {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : 0;
}
function isEmpt(v) {
  if (v == null) return true;
  const s = String(v).trim();
  return EMPTY.has(s) || s === "";
}
function isImgUrl(v) {
  if (!v) return false;
  return /^(https?:)?\/\//i.test(v) || /^data:/i.test(v) || /^blob:/i.test(v);
}

// Compute a readable, unique class name per element.
function computeClassMap(elements) {
  const used = new Map(); // slug -> count
  const map = new Map();  // id -> class
  for (const el of elements) {
    let base = slugify(el.name);
    let cls = base;
    const n = used.get(base) || 0;
    if (n > 0) cls = `${base}-${n + 1}`;
    used.set(base, n + 1);
    const final = ensureUnique(map, cls);
    map.set(el.id, `.${final}`);
  }
  return map;
}
function ensureUnique(map, cls) {
  let c = cls;
  let i = 2;
  const vals = new Set(map.values());
  while (vals.has(`.${c}`)) { c = `${cls}-${i++}`; }
  return c;
}

function propToDecls(el, includeGeometry = true, relPos = null) {
  const decls = [];
  if (includeGeometry) {
    decls.push(`position:absolute;`);
    decls.push(`left:${num(relPos ? relPos.x : el.x)}px;`);
    decls.push(`top:${num(relPos ? relPos.y : el.y)}px;`);
    decls.push(`width:${num(el.width)}px;`);
    decls.push(`height:${num(el.height)}px;`);
  }
  for (const [k, v] of Object.entries(el.props || {})) {
    if (!WHITELIST.has(k)) continue;
    if (isEmpt(v)) continue;
    // skip geometry keys already emitted above when including geometry
    if (includeGeometry && (k === "width" || k === "height")) continue;
    decls.push(`${k}:${String(v).trim()};`);
  }
  return decls;
}

// Coords map: id -> {x,y}. Elements use absolute canvas coords; children get
// positions relative to their containing parent on export via relPos.
const EMPTY_CTX = { abs: new Map(), parent: new Map() };

function buildFuncContext(elements) {
  const ctx = { abs: new Map(), parent: new Map() };
  for (const el of elements) {
    ctx.parent.set(el.id, el.parentId || null);
    ctx.abs.set(el.id, { x: el.x, y: el.y });
  }
  return ctx;
}

function elementRule(el, className, ctx) {
  let relPos = null;
  if (el.parentId && ctx.abs) {
    const p = ctx.abs.get(el.parentId);
    if (p) relPos = { x: el.x - p.x, y: el.y - p.y };
  }
  const decls = propToDecls(el, true, relPos);
  const body = decls.map(d => "  " + d).join("\n");
  return `/* ${el.name} */\n${className} {\n${body}\n}`;
}

function buildCssText(elements, opts = {}) {
  const classMap = opts.classMap || computeClassMap(elements);
  const ctx = opts.ctx || buildFuncContext(elements);
  const W = opts.pageWidth, H = opts.pageHeight;
  const pageClass = opts.pageClass || ".webfacer-page";
  const lines = [];
  lines.push(`/* Generated by WebFacer */`);
  lines.push(`body { margin: 0; }`);
  if (W && H) {
    lines.push(`${pageClass} {\n  position: relative;\n  width: ${W}px;\n  height: ${H}px;\n}`);
  } else {
    lines.push(`${pageClass} {\n  position: relative;\n}`);
  }
  lines.push("");
  for (const el of elements) {
    lines.push(elementRule(el, classMap.get(el.id), ctx));
    lines.push("");
    const clips = (el.anims || []).filter(a => (a.tracks || []).length);
    if (clips.length) {
      for (const a of clips) lines.push(buildKeyframes(el, a));
      const animList = clips.map(a => `kf-${el.id}-${a.id} ${+a.duration || 300}ms ${+(a.start || 0)}ms both`);
      lines.push(`.${classMap.get(el.id).replace(/^\./, "")}.wf-play { animation: ${animList.join(", ")}; }`);
      lines.push("");
    }
  }
  return lines.join("\n");
}

function buildKeyframes(el, clip) {
  const name = "kf-" + el.id + "-" + clip.id;
  const lines = [`@keyframes ${name} {`];
  for (const track of (clip.tracks || [])) {
    const kfs = (track.keyframes || []).slice().sort((a, b) => (a.t || 0) - (b.t || 0));
    for (const k of kfs) {
      lines.push(`  ${Math.round((k.t || 0) * 100)}% { ${track.prop}: ${k.value}; animation-timing-function: ${k.ease || "ease"}; }`);
    }
  }
  lines.push("}");
  return lines.join("\n");
}

function buildClickScript(logic, classMap) {
  if (!logic || !logic.length) return "";
  const pairs = logic.map(l => {
    const t = classMap.get(l.triggerId), g = classMap.get(l.targetId);
    if (!t || !g) return null;
    return { trigger: t.replace(/^\./, ""), target: g.replace(/^\./, "") };
  }).filter(Boolean);
  if (!pairs.length) return "";
  const body = pairs.map(p =>
    `document.querySelectorAll('.${p.trigger}').forEach(function(el){ el.addEventListener('click', function(){ var t=document.querySelector('.${p.target}'); if(!t) return; t.classList.remove('wf-play'); void t.offsetWidth; t.classList.add('wf-play'); t.addEventListener('animationend', function h(){ t.classList.remove('wf-play'); t.removeEventListener('animationend', h); }); }); });`
  ).join("\n");
  return `<script>\n(function(){\n${body}\n})();\n</script>`;
}

function elementTag(el) {
  switch (el.type) {
    case "button": return "button";
    case "link": return "a";
    case "input": return "input";
    case "image": return "img";
    case "divider": return "hr";
    case "heading": return "h2";
    case "emoji": return "div";
    default: return "div";
  }
}

function buildHtmlText(elements, opts = {}) {
  const classMap = opts.classMap || computeClassMap(elements);
  const byParent = new Map();
  for (const el of elements) {
    const key = el.parentId || "__root__";
    if (!byParent.has(key)) byParent.set(key, []);
    byParent.get(key).push(el);
  }
  const roots = byParent.get("__root__") || [];
  const docTitle = opts.title || "WebFacer 设计";

  function render(el, depth) {
    const tag = elementTag(el);
    const cls = (classMap.get(el.id) || "").replace(/^\./, "");
    const pad = "  ".repeat(depth);
    const children = byParent.get(el.id) || [];
    const kids = children.map(c => render(c, depth + 1)).join("\n");
    let open = "";
    let selfClose = false;

    if (tag === "img") {
      if (isImgUrl(el.content)) {
        open = `<img class="${cls}" src="${escapeHtml(el.content)}" alt="">`;
      } else {
        open = `<div class="${cls}" role="img" aria-label="${escapeHtml(el.name || "image")}"></div>`;
      }
      selfClose = true;
    } else if (tag === "input") {
      open = `<input class="${cls}" type="text" placeholder="${escapeHtml(el.content || "")}">`;
      selfClose = true;
    } else if (tag === "hr") {
      open = `<hr class="${cls}">`;
      selfClose = true;
    } else if (tag === "button") {
      open = `<${tag} class="${cls}">${escapeHtml(el.content || "")}</${tag}>`;
      selfClose = true;
    } else {
      const inner = escapeHtml(el.content || "");
      if (inner && children.length) {
        open = `<${tag} class="${cls}">${inner}\n${kids}`;
      } else if (inner) {
        open = `<${tag} class="${cls}">${inner}</${tag}>`;
        selfClose = true;
      } else {
        open = `<${tag} class="${cls}">\n${kids}`;
      }
    }

    if (selfClose) return pad + open;
    return pad + open + `\n${pad}</${tag}>`;
  }

  const body = roots.map(el => render(el, 1)).join("\n");
  const clickScript = buildClickScript(opts.logic || [], classMap);
  return `<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${escapeHtml(docTitle)}</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<main class="webfacer-page">
${body}
</main>
${clickScript}
</body>
</html>`;
}

WF.EMPTY_CTX = EMPTY_CTX;
WF.computeClassMap = computeClassMap;
WF.propToDecls = propToDecls;
WF.buildFuncContext = buildFuncContext;
WF.elementRule = elementRule;
WF.buildCssText = buildCssText;
WF.buildHtmlText = buildHtmlText;
})();

// ---- js/canvas.js ----
(function(){
'use strict';
// canvas.js — renders the design surface and handles all canvas interaction.
const { store } = WF;
const { getComponent } = WF;
const { clamp, debounce } = WF;
const SNAP = 4;       // movement snap (px)
const MIN_SIZE = 8;   // min element size (px)

const HANDLE_DIRS = ["nw", "n", "ne", "e", "se", "s", "sw", "w"];

function isImageUrl(v) {
  if (!v) return false;
  return /^(https?:)?\/\//i.test(v) || /^data:/i.test(v) || /^blob:/i.test(v);
}
function rectsIntersect(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

class Canvas {
  constructor(refs) {
    this.stage = refs.stage;
    this.nodeMap = new Map(); // id -> DOM node
    this.zoom = store.state.zoom;
    this._drag = null;
    this._bound = false;

    this._build();
    this._bindStore();
    this._bindPointer();
    this.render();
  }

  // ----- DOM structure -----
  _build() {
    const wrap = document.createElement("div");
    wrap.className = "canvas-wrap";
    const canvas = document.createElement("div");
    canvas.className = "canvas";
    canvas.id = "canvas";
    wrap.appendChild(canvas);
    this.stage.appendChild(wrap);
    this.wrap = wrap;
    this.canvas = canvas;

    // selection frame + resize handles
    const frame = document.createElement("div");
    frame.className = "select-frame";
    const label = document.createElement("div");
    label.className = "frame-label";
    const size = document.createElement("div");
    size.className = "frame-size";
    frame.appendChild(label);
    frame.appendChild(size);
    for (const dir of HANDLE_DIRS) {
      const h = document.createElement("div");
      h.className = "rhandle";
      h.dataset.dir = dir;
      frame.appendChild(h);
    }
    this.frame = frame;
    this.frameLabel = label;
    this.frameSize = size;
    canvas.appendChild(frame);
    // marquee selection box
    const marquee = document.createElement("div");
    marquee.className = "canvas-highlight marquee";
    marquee.style.display = "none";
    this.marquee = marquee;
    canvas.appendChild(marquee);
  }

  _bindStore() {
    store.on("change", (reason) => {
      switch (reason.type) {
        case "add":
        case "remove":
        case "structure":
          this.render();
          break;
        case "update":
          this.updateNode(reason.id);
          break;
        case "update-many":
          this.render();
          break;
        case "selection":
          this.updateSelectionFrame();
          break;
        case "zoom":
          this.layout();
          this.updateSelectionFrame();
          break;
        case "resize-canvas":
          this.layout();
          this.render();
          break;
        case "canvas":
          this.applyCanvasStyle();
          break;
        default:
          break;
      }
    });
  }

  // ----- layout / zoom -----
  layout() {
    const z = store.state.zoom;
    const W = store.state.width;
    const H = store.state.height;
    this.zoom = z;
    this.canvas.style.width = W + "px";
    this.canvas.style.height = H + "px";
    this.canvas.style.transform = `scale(${z})`;
    this.canvas.style.transformOrigin = "0 0";
    this.wrap.style.width = (W * z) + "px";
    this.wrap.style.height = (H * z) + "px";
    this.applyCanvasStyle();
  }

  applyCanvasStyle() {
    const bg = store.state.canvasBg || "#ffffff";
    this.canvas.style.backgroundColor = bg;
    this.canvas.classList.toggle("no-grid", !store.state.showGrid);
  }

  // ----- coordinate mapping -----
  _clientToCanvas(ev) {
    const rect = this.canvas.getBoundingClientRect();
    return {
      x: (ev.clientX - rect.left) / this.zoom,
      y: (ev.clientY - rect.top) / this.zoom,
    };
  }

  // ----- rendering -----
  render() {
    const docs = document.createDocumentFragment();
    this.nodeMap.clear();
    for (const el of store.elements()) {
      const node = this._buildNode(el);
      this._applyStyle(node, el);
      this.nodeMap.set(el.id, node);
      docs.appendChild(node);
    }
    this.canvas.textContent = "";
    this.canvas.appendChild(docs);
    this.canvas.appendChild(this.frame);
    this.updateSelectionFrame();
  }

  _buildNode(el) {
    let node;
    if (el.type === "image") {
      if (isImageUrl(el.content)) {
        node = document.createElement("img");
        node.src = el.content;
        node.alt = el.name || "";
        node.draggable = false;
      } else {
        node = document.createElement("div");
        node.textContent = "图片 · 在右侧设置地址";
        node.classList.add("img-ph");
      }
    } else if (el.type === "input") {
      node = document.createElement("input");
      node.type = "text";
      node.readOnly = true;
      node.tabIndex = -1;
      node.placeholder = el.content || "";
    } else {
      node = document.createElement("div");
      if (el.type === "link") node.style.textDecoration = "underline";
      node.textContent = el.content || "";
    }
    node.className = "el";
    if (el.locked) node.classList.add("locked");
    if (store.isSelected(el.id)) node.classList.add("selected");
    node.dataset.id = el.id;
    return node;
  }

  _applyStyle(node, el) {
    node.style.display = store.isHidden(el.id) ? "none" : "";
    for (const [k, v] of Object.entries(el.props || {})) {
      if (!v) continue;
      if (v === "0px" || v === "none" || v === "transparent" || v === "") continue;
      node.style.setProperty(k, String(v));
    }
    // geometry last so explicit canvas size wins over props like width:auto/100%
    node.style.left = el.x + "px";
    node.style.top = el.y + "px";
    node.style.width = el.width + "px";
    node.style.height = el.height + "px";
    // content type-dependent apply
    if (el.type === "image") node.src = el.content || "";
    if (el.type === "input") node.placeholder = el.content || "";
    if (el.type !== "image" && el.type !== "input" && el.type !== "link") node.textContent = el.content || "";
  }

  updateNode(id) {
    const el = store.getElement(id);
    const node = this.nodeMap.get(id);
    if (el && node && (el.type === "image" || el.type === "input")) { this.render(); return; }
    if (el && node) this._applyStyle(node, el);
    if (store.state.selectedId === id) this.updateSelectionFrame();
    else if (!el) this.render();
  }

  updateSelectionFrame() {
    // sync per-element 'selected' outlines
    for (const [id, node] of this.nodeMap) node.classList.toggle("selected", store.isSelected(id));
    const sel = store.selected();
    if (sel.length === 0) { this.frame.classList.remove("on"); return; }
    let left, top, right, bottom;
    for (const id of sel) {
      const el = store.getElement(id);
      if (!el) continue;
      left = left == null ? el.x : Math.min(left, el.x);
      top = top == null ? el.y : Math.min(top, el.y);
      right = right == null ? el.x + el.width : Math.max(right, el.x + el.width);
      bottom = bottom == null ? el.y + el.height : Math.max(bottom, el.y + el.height);
    }
    this.frame.classList.add("on");
    this.frame.style.left = left + "px";
    this.frame.style.top = top + "px";
    this.frame.style.width = (right - left) + "px";
    this.frame.style.height = (bottom - top) + "px";
    this.frame.classList.toggle("group", sel.length > 1);
    // hide resize handles for group selection
    this.frame.querySelectorAll(".rhandle").forEach(h => { h.style.display = sel.length > 1 ? "none" : ""; });
    if (sel.length === 1) {
      const el = store.getElement(sel[0]);
      this.frameLabel.textContent = el ? el.name : "";
      this.frameSize.textContent = el ? `${Math.round(el.width)} × ${Math.round(el.height)}` : "";
    } else {
      this.frameLabel.textContent = sel.length + " 个元素";
      this.frameSize.textContent = "";
    }
  }

  // ----- pointer interaction -----
  _bindPointer() {
    this.canvas.addEventListener("pointerdown", this._onPointerDown.bind(this));
    this.canvas.addEventListener("dblclick", this._onDblClick.bind(this));
  }

  _onPointerDown(ev) {
    const handle = ev.target.closest(".rhandle");
    if (handle) {
      if (handle.closest(".select-frame").classList.contains("on")) {
        this._startResize(ev, handle.dataset.dir);
      }
      return;
    }
    const node = ev.target.closest(".el");
    if (node) {
      const id = node.dataset.id;
      const el = store.getElement(id);
      if (!el || el.locked) return;
      if (store.isSelected(id)) this._startMove(ev, store.selected());
      else { store.select(id); this._startMove(ev, [id]); }
      return;
    }
    // empty canvas -> start marquee selection
    this._startMarquee(ev);
  }

  _onDblClick(ev) {
    const node = ev.target.closest(".el");
    if (!node) return;
    const id = node.dataset.id;
    const el = store.getElement(id);
    if (!el) return;
    // request content edit via a custom event the inspector can hook
    window.dispatchEvent(new CustomEvent("webfacer:edit-content", { detail: { id } }));
  }

  _snap(v) { return Math.round(v / SNAP) * SNAP; }

  _startMove(ev, ids) {
    const start = this._clientToCanvas(ev);
    const idSet = new Set();
    for (const id of ids) {
      idSet.add(id);
      store._descendants(id).forEach(d => idSet.add(d));
    }
    const group = [...idSet].map(id => {
      const e = store.getElement(id);
      return e ? { id, x: e.x, y: e.y } : null;
    }).filter(Boolean);
    if (!group.length) return;
    this._drag = { mode: "move", group, cStart: start, historyPushed: false };
    this._addWindowListeners();
  }

  _startMarquee(ev) {
    const start = this._clientToCanvas(ev);
    this._drag = { mode: "marquee", cStart: start, sx: start.x, sy: start.y };
    const m = this.marquee;
    m.style.display = "block";
    m.style.left = start.x + "px";
    m.style.top = start.y + "px";
    m.style.width = "0px";
    m.style.height = "0px";
    this._addWindowListeners();
  }
  _drawMarquee(cur) {
    const d = this._drag;
    const x = Math.min(d.sx, cur.x), y = Math.min(d.sy, cur.y);
    const w = Math.abs(cur.x - d.sx), h = Math.abs(cur.y - d.sy);
    const m = this.marquee;
    m.style.left = x + "px";
    m.style.top = y + "px";
    m.style.width = w + "px";
    m.style.height = h + "px";
    d.rect = { x, y, w, h };
    return { x, y, w, h };
  }

  _startResize(ev, dir) {
    const id = store.state.selectedId;
    const el = store.getElement(id);
    if (!el) return;
    const start = this._clientToCanvas(ev);
    this._drag = {
      mode: "resize", id, dir,
      cStart: start,
      startLeft: el.x, startTop: el.y,
      startRight: el.x + el.width, startBottom: el.y + el.height,
      historyPushed: false,
    };
    this._addWindowListeners();
  }

  _addWindowListeners() {
    this._onMove = this._handleMove.bind(this);
    this._onUp = this._handleUp.bind(this);
    window.addEventListener("pointermove", this._onMove);
    window.addEventListener("pointerup", this._onUp);
  }
  _removeWindowListeners() {
    if (this._onMove) window.removeEventListener("pointermove", this._onMove);
    if (this._onUp) window.removeEventListener("pointerup", this._onUp);
    this._onMove = this._onUp = null;
  }

  _handleMove(ev) {
    const d = this._drag;
    if (!d) return;
    const cur = this._clientToCanvas(ev);
    if (d.mode === "move") {
      if (!d.historyPushed) { store.pushHistory(); d.historyPushed = true; }
      const sx = d.group[0].x, sy = d.group[0].y;
      let nx = sx + (cur.x - d.cStart.x);
      let ny = sy + (cur.y - d.cStart.y);
      nx = clamp(this._snap(nx), 0, store.state.width - 1);
      ny = clamp(this._snap(ny), 0, store.state.height - 1);
      const dx = nx - sx, dy = ny - sy;
      const single = d.group.length === 1;
      for (const g of d.group) {
        const patch = { x: g.x + dx, y: g.y + dy };
        if (single) { const pid = this._hitTestParent(g.id, patch.x, patch.y); if (pid) patch.parentId = pid; }
        store.updateElement(g.id, patch, { history: false });
      }
    } else if (d.mode === "marquee") {
      this._drawMarquee(cur);
    } else if (d.mode === "resize") {
      if (!d.historyPushed) { store.pushHistory(); d.historyPushed = true; }
      const dir = d.dir;
      const dx = cur.x - d.cStart.x;
      const dy = cur.y - d.cStart.y;
      let left = d.startLeft, top = d.startTop;
      let right = d.startRight, bottom = d.startBottom;
      if (dir.includes("e")) right = d.startRight + dx;
      if (dir.includes("w")) left = d.startLeft + dx;
      if (dir.includes("s")) bottom = d.startBottom + dy;
      if (dir.includes("n")) top = d.startTop + dy;
      let w = right - left, h = bottom - top;
      if (w < MIN_SIZE) { if (dir.includes("w")) left = right - MIN_SIZE; w = MIN_SIZE; }
      if (h < MIN_SIZE) { if (dir.includes("n")) top = bottom - MIN_SIZE; h = MIN_SIZE; }
      w = clamp(w, MIN_SIZE, store.state.width);
      h = clamp(h, MIN_SIZE, store.state.height);
      store.updateElement(d.id, { x: left, y: top, width: w, height: h }, { history: false });
    }
  }

  _handleUp() {
    const d = this._drag;
    if (d && d.mode === "marquee") {
      const r = d.rect;
      if (!r || (r.w < 4 && r.h < 4)) {
        store.clearSelection();
      } else {
        const ids = store.elements().filter(el => rectsIntersect(r, { x: el.x, y: el.y, w: el.width, h: el.height })).map(el => el.id);
        store.setSelection(ids);
      }
    }
    this.marquee.style.display = "none";
    this._drag = null;
    this._removeWindowListeners();
  }

  _hitTestParent(id, nx, ny) {
    const el = store.getElement(id);
    if (!el) return null;
    const cx = nx + el.width / 2;
    const cy = ny + el.height / 2;
    const desc = new Set(store._descendants(id));
    let best = null;
    let bestArea = Infinity;
    for (const c of store.elements()) {
      if (c.id === id) continue;
      if (desc.has(c.id)) continue;
      if (!getComponent(c.type).isContainer) continue;
      const r = { x: c.x, y: c.y, w: c.width, h: c.height };
      if (cx >= r.x && cx <= r.x + r.w && cy >= r.y && cy <= r.y + r.h) {
        const a = r.w * r.h;
        if (a < bestArea) { bestArea = a; best = c; }
      }
    }
    return best ? best.id : null;
  }

  // ----- select element from outside (library drop) -----
  coordsFromClient(cx, cy) {
    const rect = this.canvas.getBoundingClientRect();
    const x = (cx - rect.left) / this.zoom;
    const y = (cy - rect.top) / this.zoom;
    const inside = cx >= rect.left && cx <= rect.right && cy >= rect.top && cy <= rect.bottom;
    return { x, y, inside };
  }

  addAt(typeKey, canvasPos) {
    const c = getComponent(typeKey);
    const x = Math.max(0, canvasPos.x - (c.size ? c.size.width : 0) / 2);
    const y = Math.max(0, canvasPos.y - (c.size ? c.size.height : 0) / 2);
    const el = store.addElement(typeKey, { x, y });
    const parentId = this._hitTestParent(el.id, el.x, el.y);
    if (parentId) store.updateElement(el.id, { parentId }, { history: false });
    store.select(el.id);
    return el;
  }

  centerOnCanvasPos(canvasPos) {
    // snap-drop position helper used by library drag-drop
    return canvasPos;
  }

  requestFocus() { this.canvas.focus(); }

  nodeFor(id) { return this.nodeMap.get(id) || null; }

  previewPlay(id) {
    const node = this.nodeMap.get(id);
    const clips = store.animsOf(id);
    if (!node || !clips.length || !node.animate) return;
    node.getAnimations && node.getAnimations().forEach(a => a.cancel());
    for (const anim of clips) {
      const dur = +anim.duration || 300;
      const delay = +(anim.start || 0);
      for (const track of (anim.tracks || [])) {
        const kfs = (track.keyframes || []).slice().sort((a, b) => (a.t || 0) - (b.t || 0));
        if (!kfs.length) continue;
        const wf = kfs.map(k => ({ [track.prop]: k.value, offset: +k.t, easing: k.ease || "ease" }));
        try { node.animate(wf, { duration: dur, delay, fill: "backwards" }); } catch (e) { /* ignore */ }
      }
    }
  }
}

WF.Canvas = Canvas;
})();

// ---- js/left-panel.js ----
(function(){
'use strict';
// left-panel.js — library (draggable components) + layers tree.
const { store } = WF;
const { COMPONENTS, LIBRARY_ORDER, getComponent } = WF;
const { showDragGhost, moveDragGhost, hideDragGhost } = WF;
class LeftPanel {
  constructor(refs, canvas) {
    this.body = refs.body;
    this.canvas = canvas;
    this.tabs = [...document.querySelectorAll("#left-tabs .panel-tab")];
    this.activeTab = "library";
    this._bindTabs();
    this._bindStore();
    this._setTab("library");
  }

  _bindTabs() {
    this.tabs.forEach(tab => {
      tab.addEventListener("click", () => this._setTab(tab.dataset.tab));
    });
  }
  _setTab(name) {
    this.activeTab = name;
    this.tabs.forEach(t => t.classList.toggle("active", t.dataset.tab === name));
    if (name === "library") this._renderLibrary();
    else this._renderLayers();
  }

  _bindStore() {
    store.on("change", (reason) => {
      if (this.activeTab === "layers") this._renderLayers();
      if (this.activeTab === "library" && (reason.type === "add" || reason.type === "remove" || reason.type === "structure")) {
        // library grid static; no re-render needed
      }
    });
  }

  // ----- Library grid -----
  _renderLibrary() {
    const grid = document.createElement("div");
    grid.className = "library-grid";
    this.body.textContent = "";
    for (const key of LIBRARY_ORDER) {
      const c = COMPONENTS[key];
      if (!c) continue;
      const item = document.createElement("div");
      item.className = "lib-item";
      item.dataset.type = key;
      item.title = `拖到画布添加「${c.label}」`;
      const thumb = document.createElement("div");
      thumb.className = "lib-thumb";
      thumb.textContent = c.icon;
      const name = document.createElement("div");
      name.className = "lib-name";
      name.textContent = c.label;
      item.appendChild(thumb);
      item.appendChild(name);
      this._makeDraggable(item, key);
      grid.appendChild(item);
    }
    this.body.appendChild(grid);
  }

  _makeDraggable(item, typeKey) {
    let ghost = null;
    item.addEventListener("pointerdown", (ev) => {
      ev.preventDefault();
      const c = getComponent(typeKey);
      ghost = showDragGhost(`＋ ${c.label}`, ev);
      const move = (e) => {
        moveDragGhost(ghost, e);
        // highlight drop target
      };
      const up = (e) => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        hideDragGhost(ghost);
        ghost = null;
        const pos = this.canvas.coordsFromClient(e.clientX, e.clientY);
        if (pos.inside) {
          this.canvas.addAt(typeKey, pos);
        }
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
    });
  }

  // ----- Layers tree -----
  _renderLayers() {
    this.body.textContent = "";
    const root = document.createElement("div");
    root.className = "layers";
    const els = store.elements();
    const childrenOf = (pid) => els.filter(e => e.parentId === pid);

    const walk = (pid, parentEl) => {
      for (const el of els.filter(e => e.parentId === pid)) {
        const row = document.createElement("div");
        row.className = "layer-row" + (store.state.selectedId === el.id ? " sel" : "");
        row.dataset.id = el.id;

        const tog = document.createElement("span");
        tog.className = "tog";
        tog.textContent = store.isHidden(el.id) ? "●" : "◐";
        tog.title = "显示/隐藏";
        tog.addEventListener("pointerdown", (ev) => { ev.stopPropagation(); });
        tog.addEventListener("click", (ev) => { ev.stopPropagation(); store.toggleHidden(el.id); });

        const icon = document.createElement("span");
        icon.className = "icon";
        icon.textContent = getComponent(el.type).icon;

        const name = document.createElement("span");
        name.className = "name";
        name.textContent = el.name;

        const type = document.createElement("span");
        type.className = "type";
        type.textContent = el.type;

        row.appendChild(tog);
        row.appendChild(icon);
        row.appendChild(name);
        row.appendChild(type);

        row.addEventListener("click", () => store.select(el.id));
        parentEl.appendChild(row);

        const kids = childrenOf(el.id);
        if (kids.length) {
          const childBox = document.createElement("div");
          childBox.className = "layer-children";
          walk(el.id, childBox);
          parentEl.appendChild(childBox);
        }
      }
    };

    walk(null, root);
    this.body.appendChild(root);
  }
}

WF.LeftPanel = LeftPanel;
})();

// ---- js/inspector.js ----
(function(){
'use strict';
// inspector.js — right-hand style editor, grouped by category.
const { store } = WF;
const { getComponent } = WF;
const SWATCHES = [
  "#ffffff", "#e5e7eb", "#111827", "#374151", "#6b7280",
  "#4f8cff", "#0ea5e9", "#10b981", "#f59e0b", "#f2635f",
  "#a855f7", "#ec4899", "#14b8a6", "#facc15", "#000000",
];

function parseLen(v) {
  const n = Number.parseFloat(v);
  return Number.isFinite(n) ? n : 0;
}
function toHex(v) {
  if (!v || String(v) === "transparent") return "#ffffff";
  const c = String(v).trim();
  if (/^#[0-9a-f]{6}$/i.test(c)) return c;
  if (/^#[0-9a-f]{3}$/i.test(c)) return "#" + c.slice(1).split("").map(x => x + x).join("");
  return "#ffffff";
}

class Inspector {
  constructor(el) {
    this.el = el;
    this._sel = null;
    this._bindStore();
    this.render();
  }
  _bindStore() {
    store.on("change", (r) => {
      if (r.type === "selection" || r.type === "structure" || r.type === "remove") {
        this.render();
      } else if (r.type === "update" && store.state.selectedId === r.id) {
        // don't rebuild on every keystroke; update header name label only
        this._syncHeaderName();
      }
    });
  }
  _syncHeaderName() {
    const input = this.el.querySelector(".insp-name");
    const el = store.getElement(this._sel);
    if (el && input && document.activeElement !== input) input.value = el.name;
  }

  _selected() {
    return store.getElement(store.state.selectedId);
  }

  render() {
    this.el.textContent = "";
    const el = this._selected();
    this._sel = el ? el.id : null;
    this._ids = store.selected();
    if (!this._ids.length && el) this._ids = [el.id];
    if (!el) {
      const empty = document.createElement("div");
      empty.className = "empty";
      empty.innerHTML = "<strong>未选中元素</strong><small>点击画布上的元素，或从左侧<br>拖入一个组件开始编辑</small>";
      this.el.appendChild(empty);
      return;
    }

    // header
    const multi = this._ids.length > 1;
    const head = document.createElement("div");
    head.className = "insp-head";
    const name = document.createElement("input");
    name.className = "insp-name";
    name.value = multi ? `已选 ${this._ids.length} 个元素` : el.name;
    name.spellcheck = false;
    if (multi) { name.readOnly = true; name.title = "多选时，下方样式修改将应用到全部选中元素"; }
    name.addEventListener("change", () => {
      if (multi) return;
      store.pushHistory();
      store.updateElement(el.id, { name: name.value.trim() || el.name }, { history: false });
    });
    const meta = document.createElement("div");
    meta.className = "insp-meta";
    meta.innerHTML = multi
      ? `<span class="chip">多选 ${this._ids.length}</span><span class="chip">修改将应用到全部</span>`
      : `<span class="chip">${el.type}</span><span class="chip">${Math.round(el.width)}×${Math.round(el.height)}</span>`;
    head.appendChild(name);
    head.appendChild(meta);
    this.el.appendChild(head);

    // groups
    const groups = this._buildGroups(el);
    for (const g of groups) {
      this.el.appendChild(this._group(g));
    }
  }

  // ----- schema -----
  _buildGroups(el) {
    const isContainer = getComponent(el.type).isContainer;
    const groups = [];

    groups.push({ title: "位置与尺寸", closed: false, fields: [
      this._field("x", "X", "number", "meta", { min: -5000, max: 8000, step: 1 }),
      this._field("y", "Y", "number", "meta", { min: -5000, max: 8000, step: 1 }),
      this._field("width", "宽 W", "number", "meta", { min: 8, max: 8000, step: 1 }),
      this._field("height", "高 H", "number", "meta", { min: 8, max: 8000, step: 1 }),
    ]});

    groups.push({ title: "排版", closed: false, fields: [
      this._field("font-family", "字体", "text", "prop", { ph: "inherit / 字体名" }),
      this._field("font-size", "字号", "number", "prop", { unit: "px", min: 1, max: 400, step: 1 }),
      this._field("font-weight", "字重", "select", "prop", { options: [
        ["300", "300 · 细"], ["400", "400 · 常规"], ["500", "500 · 中"], ["600", "600 · 半粗"], ["700", "700 · 粗"], ["800", "800 · 超粗"],
      ] }),
      this._field("color", "文字颜色", "color", "prop"),
      this._field("line-height", "行高", "number", "prop", { min: 0.5, max: 8, step: 0.1 }),
      this._field("text-align", "对齐", "seg", "prop", { options: [["left", "左"], ["center", "中"], ["right", "右"]] }),
      this._field("letter-spacing", "字间距", "number", "prop", { unit: "px", min: -10, max: 100, step: 1 }),
      this._field("text-decoration", "装饰", "seg", "prop", { options: [["none", "无"], ["underline", "下划线"], ["line-through", "删除线"]] }),
    ]});

    groups.push({ title: "背景", closed: false, fields: [
      this._field("background-color", "背景色", "color", "prop"),
      this._field("background-image", "图片/渐变", "text", "prop", { ph: "linear-gradient(...) 或 url(...)" }),
    ]});

    groups.push({ title: "边框", closed: false, fields: [
      this._field("border-width", "描边", "number", "prop", { unit: "px", min: 0, max: 60, step: 1 }),
      this._field("border-style", "线型", "select", "prop", { options: [
        ["none", "无"], ["solid", "实线"], ["dashed", "虚线"], ["dotted", "点线"],
      ] }),
      this._field("border-color", "描边色", "color", "prop"),
      this._field("border-radius", "圆角", "number", "prop", { unit: "px", min: 0, max: 1000, step: 1 }),
    ]});

    groups.push({ title: "间距", closed: false, fields: [
      this._field("padding", "内边距", "number", "prop", { unit: "px", min: 0, max: 400, step: 1 }),
      this._field("margin", "外边距", "number", "prop", { unit: "px", min: -200, max: 400, step: 1 }),
    ]});

    groups.push({ title: "效果", closed: false, fields: [
      this._field("boxShadow", "阴影", "text", "prop", { ph: "0 4px 12px rgba(0,0,0,.2)" }),
      this._field("opacity", "不透明度", "range", "prop", { min: 0, max: 1, step: 0.01 }),
      this._field("transform", "变换", "text", "prop", { ph: "rotate(8deg) scale(1.1)" }),
    ]});

    if (isContainer) {
      groups.push({ title: "容器布局", closed: false, fields: [
        this._field("display", "布局方式", "select", "prop", { options: [["block", "块级 Block"], ["flex", "弹性 Flex"]] }),
        this._field("flex-direction", "主轴方向", "seg", "prop", { options: [["row", "横向"], ["column", "纵向"]] }),
        this._field("align-items", "交叉轴对齐", "select", "prop", { options: [
          ["flex-start", "起始"], ["center", "居中"], ["flex-end", "末尾"], ["stretch", "拉伸"],
        ] }),
        this._field("justify-content", "主轴对齐", "select", "prop", { options: [
          ["flex-start", "起始"], ["center", "居中"], ["flex-end", "末尾"], ["space-between", "两端"], ["space-around", "环绕"],
        ] }),
        this._field("gap", "间距", "number", "prop", { unit: "px", min: 0, max: 200, step: 1 }),
      ]});
    }

    // content group for text-bearing elements
    const hasContent = !isContainer && el.type !== "divider";
    if (hasContent) {
      groups.push({ title: "内容", closed: false, fields: [
        this._field("content", el.type === "image" ? "图片地址" : el.type === "input" ? "占位文字" : "内容", "textarea", "meta"),
      ]});
    }

    return groups;
  }

  _field(key, label, type, target, opts = {}) {
    return { key, label, type, target, opts };
  }

  // ----- generic value get/set -----
  _get(el, f) {
    if (f.target === "meta") return el[f.key];
    return (el.props || {})[f.key];
  }
  _set(el, f, val) {
    const patch = f.target === "meta" ? { [f.key]: val } : { props: { [f.key]: val } };
    const ids = (this._ids && this._ids.length) ? this._ids : (el ? [el.id] : []);
    if (ids.length > 1) store.updateMany(ids, patch, { history: false });
    else if (ids.length) store.updateElement(ids[0], patch, { history: false });
  }

  // ----- renderers -----
  _group(g) {
    const box = document.createElement("div");
    box.className = "insp-group" + (g.closed ? " closed" : "");
    const head = document.createElement("button");
    head.className = "insp-group-head";
    head.innerHTML = `<span>${g.title}</span><span class="chev">▾</span>`;
    head.addEventListener("click", () => { box.classList.toggle("closed"); });
    const body = document.createElement("div");
    body.className = "insp-group-body";
    const twoCol = g.fields.length % 2 === 0 && g.fields.every(f => ["number", "color", "select"].includes(f.type));
    if (twoCol) body.classList.add("insp-grid");
    for (const f of g.fields) {
      const wrapped = this._fieldDom(f);
      if (wrapped) body.appendChild(wrapped);
    }
    box.appendChild(head);
    box.appendChild(body);
    return box;
  }

  _fieldDom(f) {
    const el = this._selected();
    if (!el) return null;
    const wrap = document.createElement("label");
    wrap.className = "field";
    const label = document.createElement("span");
    label.textContent = f.label;
    wrap.appendChild(label);

    let input;
    const val = this._get(el, f);

    if (f.type === "number") {
      input = document.createElement("input");
      input.type = "number";
      input.className = "ctl";
      input.min = f.opts.min; input.max = f.opts.max; input.step = f.opts.step ?? 1;
      input.value = parseLen(val);
      if (f.opts.unit) {
        const row = document.createElement("div");
        row.className = "field-row";
        row.appendChild(input);
        const unit = document.createElement("span");
        unit.className = "unit";
        unit.textContent = f.opts.unit;
        row.appendChild(unit);
        input.addEventListener("change", () => {
          store.pushHistory();
          const n = Number(input.value);
          this._set(el, f, `${isNaN(n) ? 0 : n}${f.opts.unit}`);
          this._emitSizeChange(f);
        });
        this._wrapInput(wrap, row, input);
        return wrap;
      }
      input.addEventListener("change", () => {
        store.pushHistory();
        const n = Number(input.value);
        this._set(el, f, isNaN(n) ? 0 : n);
        this._emitSizeChange(f);
      });
      wrap.appendChild(input);
      return wrap;
    }

    if (f.type === "text") {
      input = document.createElement("input");
      input.type = "text";
      input.className = "ctl";
      input.placeholder = f.opts.ph || "";
      input.value = val == null ? "" : val;
      input.addEventListener("change", () => {
        store.pushHistory();
        this._set(el, f, input.value.trim());
      });
      wrap.appendChild(input);
      return wrap;
    }

    if (f.type === "textarea") {
      input = document.createElement("textarea");
      input.className = "ctl";
      input.rows = 3;
      input.value = f.key === "content" ? (el.content || "") : (val == null ? "" : val);
      input.addEventListener("change", () => {
        store.pushHistory();
        if (f.key === "content") {
          const ids = (this._ids && this._ids.length) ? this._ids : [el.id];
          if (ids.length > 1) store.updateMany(ids, { content: input.value }, { history: false });
          else store.updateElement(el.id, { content: input.value }, { history: false });
        } else this._set(el, f, input.value);
      });
      wrap.appendChild(input);
      return wrap;
    }

    if (f.type === "select") {
      input = document.createElement("select");
      input.className = "ctl";
      for (const [v, t] of f.opts.options) {
        const o = document.createElement("option");
        o.value = v; o.textContent = t;
        if (String(val) === String(v)) o.selected = true;
        input.appendChild(o);
      }
      input.addEventListener("change", () => {
        store.pushHistory();
        this._set(el, f, input.value);
      });
      wrap.appendChild(input);
      return wrap;
    }

    if (f.type === "seg") {
      const seg = document.createElement("div");
      seg.className = "seg";
      for (const [v, t] of f.opts.options) {
        const b = document.createElement("button");
        b.type = "button";
        b.textContent = t;
        b.dataset.v = v;
        if (String(val) === String(v)) b.classList.add("on");
        b.addEventListener("click", () => {
          store.pushHistory();
          this._set(el, f, v);
          seg.querySelectorAll("button").forEach(x => x.classList.toggle("on", x === b));
        });
        seg.appendChild(b);
      }
      wrap.appendChild(seg);
      return wrap;
    }

    if (f.type === "color") {
      const row = document.createElement("div");
      row.className = "dual";
      const color = document.createElement("input");
      color.type = "color";
      color.className = "ctl";
      color.value = toHex(val);
      const text = document.createElement("input");
      text.type = "text";
      text.className = "ctl";
      text.value = val == null ? "" : String(val);
      text.placeholder = "颜色值";
      row.appendChild(color);
      row.appendChild(text);
      wrap.appendChild(row);
      // swatches
      const sw = document.createElement("div");
      sw.className = "swatches";
      for (const c of SWATCHES) {
        const s = document.createElement("div");
        s.className = "swatch";
        s.style.background = c;
        s.title = c;
        s.addEventListener("click", () => {
          store.pushHistory();
          this._set(el, f, c);
          color.value = c; text.value = c;
        });
        sw.appendChild(s);
      }
      const clear = document.createElement("button");
      clear.type = "button";
      clear.className = "pbtn";
      clear.textContent = "透明";
      clear.addEventListener("click", () => {
        store.pushHistory();
        this._set(el, f, "transparent");
        text.value = "transparent";
      });
      sw.appendChild(clear);
      wrap.appendChild(sw);

      let cpushed = false;
      color.addEventListener("input", () => {
        if (!cpushed) { store.pushHistory(); cpushed = true; }
        this._set(el, f, color.value);
      });
      color.addEventListener("change", () => { cpushed = false; this._set(el, f, color.value); });
      text.addEventListener("change", () => {
        store.pushHistory();
        const v = text.value.trim();
        this._set(el, f, v);
        color.value = toHex(v);
      });
      return wrap;
    }

    if (f.type === "range") {
      input = document.createElement("input");
      input.type = "range";
      input.className = "ctl";
      input.min = f.opts.min; input.max = f.opts.max; input.step = f.opts.step ?? 0.01;
      input.value = val == null ? f.opts.max : val;
      const valLabel = document.createElement("span");
      valLabel.style.cssText = "font-size:11px;color:var(--text-dim);margin-left:6px;min-width:36px;text-align:right";
      const pct = Math.round((Number(input.value) * 100));
      valLabel.textContent = pct + "%";
      const row = document.createElement("div");
      row.className = "field-row";
      row.appendChild(input);
      row.appendChild(valLabel);
      let pushed = false;
      input.addEventListener("input", () => {
        const v = Number(input.value);
        valLabel.textContent = Math.round(v * 100) + "%";
        if (!pushed) { store.pushHistory(); pushed = true; }
        this._set(el, f, v);
      });
      input.addEventListener("change", () => { pushed = false; });
      wrap.appendChild(row);
      return wrap;
    }

    return null;
  }

  _wrapInput(wrap, row, input) {
    wrap.appendChild(row);
  }
  _emitSizeChange(f) {
    // size/pos changes update the frame size chip in header intact; no extra work
  }
}

WF.Inspector = Inspector;
})();

// ---- js/code-preview.js ----
(function(){
'use strict';
// code-preview.js — live source preview (current element CSS, full CSS, HTML).
const { store } = WF;
const { buildCssText, buildHtmlText, elementRule, computeClassMap, buildFuncContext } = WF;
const { escapeHtml } = WF;
class CodePreview {
  constructor(root) {
    this.root = root;          // #code-preview
    this.tabs = [...root.querySelectorAll(".cp-tab")];
    this.code = root.querySelector("#cp-code");
    this.active = "css";
    this.visible = false;
    this._bindTabs();
    this._bindActions();
    this._bindStore();
  }

  _bindTabs() {
    this.tabs.forEach(t => t.addEventListener("click", () => {
      this.active = t.dataset.tab;
      this.tabs.forEach(x => x.classList.toggle("active", x === t));
      this.render();
    }));
  }
  _bindActions() {
    this.root.querySelector("#cp-close").addEventListener("click", () => this.toggle(false));
    this.root.querySelector("#cp-copy").addEventListener("click", () => {
      const text = this.code.textContent;
      navigator.clipboard.writeText(text).then(() => window.dispatchEvent(new CustomEvent("webfacer:toast", { detail: { text: "已复制", ok: true } })));
    });
  }
  _bindStore() {
    store.on("change", () => { if (this.visible) this.render(); });
  }

  toggle(show) {
    this.visible = show == null ? !this.visible : show;
    this.root.hidden = !this.visible;
    if (this.visible) this.render();
  }

  _currentText() {
    const elements = store.elements();
    const classMap = computeClassMap(elements);
    const ctx = buildFuncContext(elements);
    const W = store.state.width, H = store.state.height;
    const sel = store.getElement(store.state.selectedId);
    if (this.active === "css") {
      if (!sel) return "/* 请先在画布上选中一个元素，查看它的 CSS。 */\n";
      return elementRule(sel, classMap.get(sel.id), ctx) + "\n";
    }
    if (this.active === "html") {
      return buildHtmlText(elements, { classMap, title: store.state.name, logic: store.logicEdges() });
    }
    // all css
    return buildCssText(elements, { classMap, ctx, pageWidth: W, pageHeight: H });
  }

  render() {
    const isCss = this.active === "css" || this.active === "all";
    const text = this._currentText();
    this.code.textContent = text;
    const esc = escapeHtml(text);
    this.code.innerHTML = isCss ? this._hlCss(esc) : this._hlHtml(esc);
  }

  _hlCss(esc) {
    let out = esc.replace(/\/\*[\s\S]*?\*\//g, (m) => `<span class="tok-cmt">${m}</span>`);
    out = out.replace(/^(\s*)([.#][A-Za-z0-9_-]+)/gm, (m, p1, p2) => `${p1}<span class="tok-sel">${p2}</span>`);
    out = out.replace(/(^|\s)([a-zA-Z-]+)(\s*:)/gm, (m, p1, p2, p3) => `${p1}<span class="tok-prop">${p2}</span>${p3}`);
    return out;
  }
  _hlHtml(esc) {
    return esc.replace(/(&lt;\/?)([a-zA-Z0-9-]+)/g, (m, a, b) => `${a}<span class="tok-sel">${b}</span>`);
  }
}

WF.CodePreview = CodePreview;
})();

// ---- js/exporter.js ----
(function(){
'use strict';
// exporter.js — write index.html + style.css to a user-chosen folder,
// with a download fallback when the File System Access API is unavailable.
const { store } = WF;
const { buildCssText, buildHtmlText, computeClassMap, buildFuncContext } = WF;
function toast(text, ok = true) {
  window.dispatchEvent(new CustomEvent("webfacer:toast", { detail: { text, ok } }));
}

class Exporter {
  constructor(canvas) {
    this.canvas = canvas;
    this.dirHandle = null;
    this.menu = null;
  }

  get support() { return typeof window.showDirectoryPicker === "function"; }
  get folderName() { return this.dirHandle ? this.dirHandle.name : null; }

  _buildFiles() {
    const elements = store.elements();
    const classMap = computeClassMap(elements);
    const ctx = buildFuncContext(elements);
    const W = store.state.width, H = store.state.height;
    const pageClass = ".webfacer-page";
    const css = buildCssText(elements, { classMap, ctx, pageWidth: W, pageHeight: H, pageClass });
    const html = buildHtmlText(elements, { classMap, title: store.state.name, logic: store.logicEdges() });
    return { html, css };
  }

  async chooseFolder() {
    if (!this.support) throw new Error("当前浏览器不支持选择文件夹，将改用下载方式。");
    this.dirHandle = await window.showDirectoryPicker({ mode: "readwrite" });
    window.dispatchEvent(new CustomEvent("webfacer:exportfolder"));
    return this.dirHandle;
  }

  async _writeFile(handle, name, content) {
    const fh = await handle.getFileHandle(name, { create: true });
    const w = await fh.createWritable();
    await w.write(content);
    await w.close();
  }

  async exportToFolder(promptIfMissing = true) {
    if (!this.dirHandle) {
      if (!this.support) { this.downloadFiles(); return; }
      if (!promptIfMissing) { toast("尚未选择导出文件夹", false); return; }
      try { await this.chooseFolder(); }
      catch (e) { if (e.name === "AbortError") return; this.downloadFiles(); return; }
    }
    const { html, css } = this._buildFiles();
    try {
      await this._writeFile(this.dirHandle, "index.html", html);
      await this._writeFile(this.dirHandle, "style.css", css);
      toast(`已导出到「${this.dirHandle.name}」 (index.html + style.css)`);
    } catch (e) {
      toast("写入文件夹失败：" + e.message, false);
    }
  }

  downloadFiles() {
    const { html, css } = this._buildFiles();
    this._download("index.html", html);
    this._download("style.css", css);
    toast("已开始下载 index.html 和 style.css");
  }

  _download(name, content) {
    const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = name;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 500);
  }

  // ----- dropdown menu on the export button -----
  attachMenu(btn) {
    btn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      this.toggleMenu(btn);
    });
  }
  toggleMenu(btn) {
    if (this.menu) { this.closeMenu(); return; }
    const m = document.createElement("div");
    m.className = "export-menu";
    m.style.cssText = "position:fixed;top:44px;right:12px;background:var(--panel-3);border:1px solid var(--border);border-radius:8px;padding:6px;z-index:120;box-shadow:0 10px 30px rgba(0,0,0,.5);display:flex;flex-direction:column;gap:2px;min-width:200px";
    const mk = (icon, label, fn) => {
      const b = document.createElement("button");
      b.type = "button";
      b.style.cssText = "text-align:left;background:transparent;border:none;color:var(--text);padding:8px 10px;border-radius:5px;cursor:pointer;font-size:12px;font-family:var(--font)";
      b.textContent = `${icon}  ${label}`;
      b.addEventListener("mouseenter", () => b.style.background = "var(--panel-2)");
      b.addEventListener("mouseleave", () => b.style.background = "transparent");
      b.addEventListener("click", () => { this.closeMenu(); fn(); });
      m.appendChild(b);
    };
    mk("📁", this.dirHandle ? `导出到「${this.dirHandle.name}」` : "选择文件夹并导出…", () => this.exportToFolder(true));
    mk("⬇", "下载 index.html / style.css", () => this.downloadFiles());
    this.menu = m;
    document.body.appendChild(m);
    setTimeout(() => document.addEventListener("pointerdown", this._closeOut = () => this.closeMenu()), 0);
  }
  closeMenu() {
    if (this.menu) this.menu.remove();
    this.menu = null;
    if (this._closeOut) { document.removeEventListener("pointerdown", this._closeOut); this._closeOut = null; }
  }
}

WF.Exporter = Exporter;
})();

